import Service from "#class/service";
import type { PolisDetails, PolisId, PolisVersieRij, PolisVersieId, RowRes, Validator, Polisdata } from "#types";

/**
 * Toegang tot de versiehistorie van een polis.
 *
 * Elke polis bestaat uit één of meer versies; deze service haalt de lijst met
 * versies op ({@link PolisVersieRij}) en de verzekeringsdetails van een
 * specifieke versie ({@link PolisDetails}).
 */
export default class PolisversieService extends Service {
    /**
     * Haalt een overzicht van alle versies van een polis op.
     *
     * @param polisId - Het nummer van de polis waarvan de versies worden opgehaald.
     * @param validator - Optioneel filter; standaard worden alle rijen teruggegeven.
     * @returns De versierijen {@link PolisVersieRij} die aan `validator` voldoen — een lege array als er geen match is.
     */
    async getVersieRows(
        polisId: PolisId,
        validator: Validator<PolisVersieRij> = () => true,
        includedCanceledVersions = false,
    ): Promise<PolisVersieRij[]> {
        const res = await this.session.getAxon<RowRes<PolisVersieRij>>(`policies/${polisId}/policy-versions`);
        return res.rows.filter(row => validator(row) && (includedCanceledVersions || !row.isCancelled));
    }

    /**
     * Haalt de polisdetails van één polisversie op.
     *
     * @param polisId - Het polisnummer waartoe de versie behoort.
     * @param versieId - De versie waarvan de details worden opgehaald.
     * @returns De {@link PolisDetails} van de opgegeven versie.
     * @throws Wanneer `versieId` niet bij `polisId` hoort, of de polis niet bestaat.
     */
    async getVersieDetails(polisId: PolisId, versieId: PolisVersieId): Promise<PolisDetails> {
        return await this.session.getAxon<PolisDetails>(
            `policies/${polisId}/${versieId}/${versieId}/insurance-detail`,
        );
    }

    /**
     * Haalt de polisdetails van de meest recente polisversie op.
     * 
     * @param polisdata - De {@link Polisdata} van de polis.
     * @returns De {@link PolisDetails} van de polisversie.
     */
    async getActueleVersieDetails(polisdata: Polisdata): Promise<PolisDetails> {
        return await this.getVersieDetails(polisdata.externalIdentifier, polisdata.policyVersionExtId);
    }
}